umber" min="1" class="input" value="<?= (int) $plan['max_usuarios'] ?>" required></div><div><label class="label">Empleados</label><input name="max_empleados" type="number" min="1" class="input" value="<?= (int) $plan['max_empleados'] ?>" required></div></div><label class="flex items-center gap-2 text-xs text-slate-600"><input type="checkbox" name="activo" value="1" class="checkbox"<?= checked((bool) $plan['activo']) ?>> Disponible para nuevas empresas</label><button type="submit" class="btn-primary w-full">Guardar cambios</button></form></details></section><?php endforeach; ?></div>
